pub fn w_same_name_and_sibling_paths_are_not_collapsed() -> bool {
    {
        let paths = identity_fixture_capture().occurrences.clone();
        (((((((matching_path_count(
            paths.clone(),
            "same".to_string(),
            "nested_same_name".to_string(),
        ) == 3)
            && (matching_let_count(
                paths.clone(),
                "same".to_string(),
                "nested_same_name".to_string(),
            ) == 1))
            && (matching_binder_declaration_count(
                paths.clone(),
                "same".to_string(),
                "nested_same_name".to_string(),
            ) == 1))
            && (matching_reference_count(
                paths.clone(),
                "same".to_string(),
                "nested_same_name".to_string(),
            ) == 1))
            && (matching_path_count(
                paths.clone(),
                "branch_value".to_string(),
                "sibling_arms".to_string(),
            ) == 4))
            && (matching_binder_declaration_count(
                paths.clone(),
                "branch_value".to_string(),
                "sibling_arms".to_string(),
            ) == 2))
            && (matching_reference_count(
                paths.clone(),
                "branch_value".to_string(),
                "sibling_arms".to_string(),
            ) == 2))
    }
}

pub fn w_parameter_and_lambda_paths_are_complete() -> bool {
    {
        let paths = identity_fixture_capture().occurrences.clone();
        (((((((((((matching_binder_declaration_count(
            paths.clone(),
            "only_parameter".to_string(),
            "parameter_once".to_string(),
        ) == 1)
            && (matching_reference_count(
                paths.clone(),
                "only_parameter".to_string(),
                "parameter_once".to_string(),
            ) == 1))
            && (matching_binder_declaration_count(
                paths.clone(),
                "lambda_parameter".to_string(),
                "lambda_once".to_string(),
            ) == 1))
            && (matching_reference_count(
                paths.clone(),
                "lambda_parameter".to_string(),
                "lambda_once".to_string(),
            ) == 1))
            && matching_paths_have_minimum_ancestry(
                paths.clone(),
                "only_parameter".to_string(),
                "parameter_once".to_string(),
                2,
            ))
            && matching_paths_have_minimum_ancestry(
                paths.clone(),
                "lambda_parameter".to_string(),
                "lambda_once".to_string(),
                3,
            ))
            && binder_pair_holds(
                identity_fixture_capture(),
                "direct_bind".to_string(),
                "direct_binder".to_string(),
            ))
            && binder_pair_holds(
                identity_fixture_capture(),
                "explicit_bind".to_string(),
                "explicit_alias".to_string(),
            ))
            && binder_pair_holds(
                identity_fixture_capture(),
                "shorthand_only".to_string(),
                "shorthand_binder".to_string(),
            ))
            && binder_pair_holds(
                identity_fixture_capture(),
                "positional_bind".to_string(),
                "positional_binder".to_string(),
            ))
            && binder_pair_holds(
                identity_fixture_capture(),
                "nested_bind".to_string(),
                "nested_binder".to_string(),
            ))
    }
}
